def _validate_key_handle(value: Any, field: str) -> str:
    """句柄必须为非空字符串且不是 PEM 文本，返回去空白后的句柄。"""
    if not isinstance(value, str) or not value.strip():
        raise ValidationError(f"缺少字段或字段为空: {field}")
    handle = value.strip()
    if _PEM_MARKER in handle:
        raise ValidationError(f"字段 {field} 必须为句柄，而非 PEM 密钥文本")
    return handle


def _is_expired(expires_at: Any) -> bool:
    """凭证正文的 expires_at 已到期（当前时间 >= expires_at）即 True。

    服务端签发的 expires_at 已按严格格式校验；此处为只读判定，缺省
    （无字段/空）视为无期限。任何解析异常都按未到期处理，绝不抛出，
    以免影响锚定/签名等既有分类原因。
    """
    if not isinstance(expires_at, str) or not expires_at:
        return False
    try:
        return datetime.now(timezone.utc) >= _parse_utc_z(expires_at)
    except ValueError:
        return False


def _parse_pointer(pointer: str, label: str = "disclose") -> Tuple[str, ...]:
    """解析相对 claims 的 RFC6901 JSON Pointer 为 token 元组。

    仅做语法解析：必须为以 "/" 开头的字符串，按 "/" 分段并对
    "~1"/"~0" 反转义（顺序不可颠倒）；根指针 "" 与数组索引语义在
    _resolve_pointer 中按业务规则拒绝。label 为报错中的字段名。
    """
    if not isinstance(pointer, str):
        raise ValidationError(f"{label} 路径必须为字符串")
    if not pointer.startswith("/"):
        raise ValidationError(
            f"{label} 路径非法（须以 / 开头）: {pointer!r}"
        )
    tokens: List[str] = []
    for raw in pointer.split("/")[1:]:
        if "~" in raw:
            # RFC6901：~ 后只能跟 0 或 1，且先还原 ~1 再还原 ~0
            idx = 0
            while idx < len(raw):
                if raw[idx] == "~" and (
                    idx + 1 >= len(raw) or raw[idx + 1] not in "01"
                ):
                    raise ValidationError(
                        f"{label} 路径含非法转义（~ 后须为 0 或 1）: {pointer!r}"
                    )
                idx += 1
        tokens.append(raw.replace("~1", "/").replace("~0", "~"))
    return tokens


def _resolve_pointer(
    claims: Dict[str, Any],
    tokens: Tuple[str, ...],
    pointer: str,
    label: str = "disclose",
) -> Any:
    """沿 token 导航 claims 并返回目标值。

    禁根（空 token）、禁数组索引（任一步进入数组）、键不存在或
    经过非对象叶子均按越界/未命中拒绝。
    """
    if not tokens:
        raise ValidationError(f"{label} 不允许根路径（零披露请传空列表）")
    current: Any = claims
    for token in tokens:
        if isinstance(current, list):
            raise ValidationError(
                f"{label} 路径不允许数组索引: {pointer!r}"
            )
        if not isinstance(current, dict) or token not in current:
            raise ValidationError(
                f"{label} 路径越界或未命中 claims 属性: {pointer!r}"
            )
        current = current[token]
    return current


def _validate_disclose(
    claims: Dict[str, Any], disclose: Any
) -> List[Tuple[str, Tuple[str, ...]]]:
    """校验 disclose 列表并返回 (原路径, token 元组) 列表。

    - disclose 必须为列表；元素须为以 / 开头的合法 RFC6901 指针字符串；
    - 路径须命中 claims 属性：禁根、禁数组索引、禁越界；
    - 路径不得重复、不得存在祖先/后代重叠（含已覆盖的深层路径）。
    """
    if not isinstance(disclose, list):
        raise ValidationError("字段 disclose 必须为数组")
    parsed: List[Tuple[str, Tuple[str, ...]]] = []
    seen_tokens: List[Tuple[str, ...]] = []
    for pointer in disclose:
        tokens = _parse_pointer(pointer)
        if tokens in seen_tokens:
            raise ValidationError(f"disclose 路径重复: {pointer!r}")
        for existing in seen_tokens:
            if tokens[: len(existing)] == existing:
                raise ValidationError(
                    f"disclose 路径存在祖先重叠: {pointer!r} 被已选路径覆盖"
                )
            if existing[: len(tokens)] == tokens:
                raise ValidationError(
                    f"disclose 路径存在祖先重叠: 已选路径被 {pointer!r} 覆盖"
                )
        _resolve_pointer(claims, tokens, pointer)
        parsed.append((pointer, tokens))
        seen_tokens.append(tokens)
    return parsed


def _project_claims(
    claims: Dict[str, Any],
    parsed: List[Tuple[str, Tuple[str, ...]]],
) -> Dict[str, Any]:
    """按解析后的路径从 claims 提取投影；路径值整体保留（数组作叶子）。"""
    projection: Dict[str, Any] = {}
    for pointer, tokens in parsed:
        value = _resolve_pointer(claims, tokens, pointer)
        target = projection
        for key in tokens[:-1]:
            target = target.setdefault(key, {})
        target[tokens[-1]] = value
    return projection


def _validate_request_disclose(disclose: Any) -> List[str]:
    """校验展示请求的 disclose（请求阶段尚无凭证，不做命中/数组校验）。

    缺省或 null 视为零披露空列表；必须为列表，元素为以 / 开头的合法
    RFC6901 指针（禁根路径、合法 ~0/~1 转义），不重复、无祖先/后代
    重叠。路径是否命中具体凭证 claims 留待 present 时结合凭证校验。
    """
    if disclose is None:
        return []
    if not isinstance(disclose, list):
        raise ValidationError("字段 disclose 必须为数组")
    paths: List[str] = []
    seen_tokens: List[Tuple[str, ...]] = []
    for pointer in disclose:
        tokens = _parse_pointer(pointer)
        if not tokens:
            raise ValidationError("disclose 不允许根路径（零披露请传空列表）")
        if tokens in seen_tokens:
            raise ValidationError(f"disclose 路径重复: {pointer!r}")
        for existing in seen_tokens:
            if tokens[: len(existing)] == existing:
                raise ValidationError(
                    f"disclose 路径存在祖先重叠: {pointer!r} 被已选路径覆盖"
                )
            if existing[: len(tokens)] == tokens:
                raise ValidationError(
                    f"disclose 路径存在祖先重叠: 已选路径被 {pointer!r} 覆盖"
                )
        paths.append(pointer)
        seen_tokens.append(tokens)
    return paths


def _validate_issuer_dids(issuer_dids: Any) -> Optional[List[str]]:
    """校验展示请求的 issuer_dids 白名单。

    缺省或 null 返回 None（不限定签发者）；须为列表，元素为非空字符串
    且不重复。显式空列表是合法的空白名单（不接受任何签发者，present
    时一律签发者不符），按原样保留以区别于省略/null 的不限定。
    """
    if issuer_dids is None:
        return None
    if not isinstance(issuer_dids, list):
        raise ValidationError("字段 issuer_dids 必须为数组")
    allowlist: List[str] = []
    for value in issuer_dids:
        if not isinstance(value, str) or not value:
            raise ValidationError(
                "字段 issuer_dids 元素必须为非空字符串"
            )
        if value in allowlist:
            raise ValidationError(f"issuer_dids 重复: {value}")
        allowlist.append(value)
    return allowlist


# 谓词证明支持的操作符
_PREDICATE_OPS = ("exists", "eq", "gte", "lte")


def _is_number(value: Any) -> bool:
    """非布尔数字（bool 是 int 的子类，须显式排除）。"""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


# 凭证模式 schema_id：小写字母开头，仅含小写字母、数字、下划线、连字符，
# 长度 1..64。
SCHEMA_ID_RE = re.compile(r"^[a-z][a-z0-9_-]{0,63}$")

# RFC6901 数组索引："0" 或无前导零的多位十进制数字。
_JSON_POINTER_ARRAY_INDEX_RE = re.compile(r"^(?:0|[1-9][0-9]*)$")

# claim_types 允许的六类 JSON 值。
SCHEMA_CLAIM_TYPES: Tuple[str, ...] = (
    "string",
    "number",
    "integer",
    "boolean",
    "object",
    "array",
)

# verify 时签名合法但模式约束校验失败的固定原因。
SCHEMA_VALIDATION_FAILED_REASON = "schema validation failed"

# verify-with-schema 请求结构或模式参数非法的固定原因。
SCHEMA_VERIFY_INVALID_REQUEST_REASON = "请求参数无效"
# verify-with-schema 按请求模式参数在本租户查不到模式的固定原因。
SCHEMA_VERIFY_SCHEMA_NOT_FOUND_REASON = "凭证模式不存在"
# verify-with-schema 正文模式绑定与请求参数/模式摘要不一致的固定原因。
SCHEMA_VERIFY_BINDING_MISMATCH_REASON = "凭证模式绑定不一致"

# 模式指针在 claims 中未命中的内部哨兵（不得对外暴露）。
_SCHEMA_POINTER_MISSING = object()


def schema_canonical_bytes(payload: Dict[str, Any]) -> bytes:
    """模式注册内容的规范化 JSON（递归键升序、紧凑、UTF-8）。"""
    return crypto.canonicalize(payload)


def schema_content_digest(payload: Dict[str, Any]) -> str:
    """模式注册内容规范化 JSON 的 SHA-256 小写十六进制。"""
    return hashlib.sha256(schema_canonical_bytes(payload)).hexdigest()


