                row = self._build_presentation_row_locked(
                    tenant_id,
                    bucket,
                    credential_id,
                    item["disclose"],
                    challenge,
                    expires_at,
                    bool(item.get("holder_binding", False)),
                )
                built.append(row)
            # 全部项校验与签名通过后才统一写入并记审计、落盘；记录与
            # 审计同次原子提交，落盘失败整体回滚。
            snapshot = self._snapshot_locked()
            try:
